  $('aconst').addEventListener('change', e => { S.areaConst = e.target.value; if (S.areaMode !== 'const') S.areaMode = 'const'; re(); });
  for (const k of Object.keys(S.adv)) $('adv-' + k).addEventListener('change', e => { S.adv[k] = e.target.value; re(); });
